// 11 техник в виде интерактивных сценариев. Методики основаны на подходе ТВП (Трансцендентная
// Ведическая Психология); тексты шагов пересказаны своими словами и адаптированы под экран, голос и холст.
//
// Типы шагов: say (текст), ask (вопрос), input (поле, заполняется всегда), scale (замер 1–10),
// timer (пауза/визуализация), loop (цикл «Есть ещё / Больше ничего нет»), each (повтор для
// каждого элемента), choice (выбор), canvas (холст), mapview (просмотр карты), timeline (линия
// времени), tlview, write (шаг письма), burn (сжигание), do (действие без экрана).
// only: ['solo','guide','pair'] — шаг только в этих режимах. hint — подсказка ведущему (режим пары).
// quick: [...] — варианты ответа кнопками. Подстановки {person}, {topic}… — из ответов.
import { blocksOf, LEVELS } from './canvas.js';

const say = (text, o) => ({ t: 'say', text, ...o });
const ask = (text, key, o) => ({ t: 'ask', text, key, ...o });
const input = (text, key, o) => ({ t: 'input', text, key, ...o });
const scale = (text, key, o) => ({ t: 'scale', text, key, ...o });
const timer = (text, sec, o) => ({ t: 'timer', text, sec, ...o });
const loop = (id, steps, o) => ({ t: 'loop', id, steps, ...o });
const each = (items, as, steps, o) => ({ t: 'each', items, as, steps, ...o });
const canvas = (text, o) => ({ t: 'canvas', text, ...o });
const act = fn => ({ t: 'do', fn });
const burn = (text, source, title) => ({ t: 'burn', text, source, title });

const ACTIONS = ['убежать', 'спрятаться', 'замереть', 'исчезнуть', 'напасть'];
const EGO = ['маленький(ая)', 'слабый(ая)', 'беззащитный(ая)', 'ничтожный(ая)', 'жалкий(ая)', 'уязвимый(ая)', 'агрессивный(ая)'];
const EMO = ['страх', 'обида', 'гнев', 'раздражение', 'вина', 'стыд'];
const FEEL_HINT = 'Если партнёр не может подобрать слово — откройте 💗 Таблицу чувств и медленно зачитайте ему названия групп.';

// Цепочка «вынь и покажи»: слова → чувство → каким я становлюсь → куда тянет действовать.
// Повторяется по кругу, пока внутри не станет пусто. to — кому показываем (дательный падеж).
function vent(id, to, { words = `Что тебе хочется высказать ${to}? Произнеси это — например: «Ты меня выводишь из себя». Вынь эти слова из себя и предъяви ${to}.`, prompt, done = 'Мне больше нечего сказать', after } = {}) {
  const steps = [];
  if (words) steps.push(ask(words, null, { hint: 'Не комментируйте и не разбирайте ответы — просто ведите по цепочке.' }));
  steps.push(
    ask(`Какое чувство стоит за этим? Представь, что вынимаешь его руками из груди и протягиваешь ${to}. Сами руки остаются на месте — всё происходит в воображении.`, null, { feel: true, quick: EMO, hint: FEEL_HINT }),
    ask(`Каким(ой) ты становишься, когда в тебе это чувство? Вынь это состояние и тоже предъяви ${to}.`, null, { quick: EGO }),
    ask(`Куда тебя тянет в таком состоянии — сбежать, укрыться, застыть, раствориться или наброситься? Вынь это желание и предъяви ${to}. Скажи прямо: «Мне хочется…»`, null, { quick: ACTIONS }),
  );
  const out = [loop(id, steps, { prompt: prompt || `Ещё раз окинь взглядом всю ситуацию. Осталось ли что-то, что хочется сказать или предъявить ${to}?`, more: 'Есть ещё', done })];
  out.push(say(after || `Вынь из себя ощущение «${done}» и тоже предъяви его ${to}.`));
  return out;
}

const CLOSE_EYES = timer('Устройся поудобнее: руки и ноги не скрещены, ладони лежат на коленях, ступни на полу. Закрой глаза и сделай три неспешных вдоха и выдоха — пусть тело обмякнет. Не рассуждай и не анализируй, просто отвечай первым, что приходит.', 30, { breath: true });

// «Перенос сознания» на лист (холст)
const TRANSFER = timer('Шаг «Перенос сознания». Этот квадрат — твоё поле. В воображении помести в него всё о себе: сильные стороны, опору и уверенность; слабости и уязвимые места; потенциал — и тот, что ты знаешь, и тот, о котором не догадываешься; скрытые и забытые способности; самого(саму) себя; и весь мир вокруг.', 60, { title: 'Перенос сознания' });

const has = t => S => S.data.map.items.some(i => i.type === t);
const needBlocks = (side, max = 3) => S => {
  const n = blocksOf(S.data.map).filter(b => !side || b.side === side).length;
  if (!n) return 'Нужна хотя бы одна блокада (в паре — перенесите её с листа партнёра).';
  if (n > max) return `Оставь не больше ${max} блокад — лишние удали.`;
  return null;
};

// Проработка каждой блокады: выгрузить всё → забрать ресурс → вернуться в свою точку → перечеркнуть
const blocksCycle = (side, home = '«Я»') => each(S => blocksOf(S.data.map).filter(b => !side || b.side === side), 'b', [
  say('Коснись блокады «{label}» — она отнимает {pct}% твоих сил. Закрой глаза и ощути её.', { title: 'Блокада {n}', hint: 'Блокада {n}: «{label}». Проведите партнёра по цепочке выгрузки.' }),
  ...vent('block', 'блокаде', { words: 'Что тебе хочется высказать этой блокаде? Произнеси, вынь эти слова из себя и предъяви ей.' }),
  timer(`Какая сила спрятана в этой блокаде? Забери её себе, вернись в точку ${home} и разлей эту силу по телу — пусть она тебя заполнит.`, 30),
  act(S => { const b = S.data.map.items.find(i => i.id === S.vars.id); if (b) b.cleared = true; }),
  say('Эта блокада проработана — перечеркни её. На холсте она уже зачёркнута.'),
]);

// Колодец: собрать всё, найти главное убеждение, отпустить, сжечь, найти новое
function wellCycle({ beliefQ, chest = 'на самом дне колодца лежит ресурс', example = '' }) {
  return [
    timer('Коснись колодца и представь, как в него стекаются все блокады и корень. Накрой колодец крышкой.', 20),
    ask(beliefQ, 'old', { hint: 'Запишите это убеждение словами партнёра.' }),
    timer('Не убирая пальца с колодца, мысленно опусти туда это убеждение.', 15),
    ask('Спроси себя: «Каково мне будет, если я прямо сейчас отпущу и блокады, и это убеждение?» Если поднимается тревога, протест или что-то неприятное — отправь и это в колодец.', null, { feel: true }),
    burn('Убери палец, сними крышку и представь, как всё, что копилось в колодце, поднимается наружу и сгорает дотла. Это тебе больше не нужно. Нажми «Сжечь».', S => S.data.fields.old || '', 'Старое убеждение'),
    act(S => { const w = S.data.map?.items.find(i => i.type === 'well'); if (w) w.cleared = true; }),
    ask(`А теперь заметь: ${chest}. Он полностью противоположен старому убеждению. Что это за сила? Возьми её, напитайся ею и сформулируй своё НОВОЕ УБЕЖДЕНИЕ.${example}`, 'belief', { belief: true }),
    say('Громко и отчётливо скажи: «Старое убеждение больше не действует. Теперь я живу с новым: {belief}».'),
    act(S => { if (S.data.map) S.data.map.belief = S.data.fields.belief || ''; }),
  ];
}

// ---------------- Сценарии ----------------

const tablet = [
  ask('Какое чувство будем гасить?', 'feeling', { title: '1. Чувство', big: true, quick: ['страх', 'обида', 'гнев', 'раздражение'], single: true, feel: true }),
  ask('Откуда это чувство давит на тебя — {feeling}? Придай ему какой-нибудь образ. Оно может находиться справа или слева, над тобой или под тобой, впереди или за спиной.', 'side', { title: '2. Откуда давит', big: true, quick: ['справа', 'слева', 'сверху', 'снизу', 'спереди', 'сзади'], single: true }),
  ask('Куда в теле оно бьёт и что делает? Например: страх стискивает сердце.', 'hit', { title: '3. Куда бьёт', big: true }),
  timer('Войди в это чувство и стань им. Взгляни на себя его глазами — с той стороны, где оно находится.', 20, { title: '4. Стань чувством', big: true }),
  timer('Делай с собой то же, что делает это чувство, только сильнее. Если страх стискивает сердце — сожми его ещё крепче. Говори от лица чувства: «Я — эта эмоция, я тобой управляю», «Я сильнее, ты ничего не сможешь». Нагнетай как можно сильнее — пока не ощутишь себя самым сильным.', 40, { title: '5. Действуй как чувство', big: true }),
  timer('Вернись в себя и забери чувство с собой. Скажи: «Я забираю обратно власть над этой эмоцией. Эта эмоция — я сам(а): {feeling}». Оно просто откололось от тебя, а теперь ты возвращаешь его и управление им.', 25, { title: '6. Вернись в себя', big: true }),
  timer('Разлей это управление по всему телу — до каждой клетки, как силу и уверенность. Скажи: «Эта эмоция — часть меня. Мне нечего бояться: я и есть {feeling}».', 25, { title: 'Разлей силу', big: true }),
  scale('Насколько сильно чувство сейчас? 1 — почти не ощущаю, 10 — очень сильно.', 'after'),
];

const mirror = [
  say('Эта практика — о том, чтобы простить себя. Идея такая: если в жизни случилось что-то плохое, значит, вернулось то, что когда-то сделали другим мы сами. Вспоминать конкретного человека и извиняться перед ним не нужно — важно, что в нас есть след, который однажды позволил ранить другого. Делай всё от души.', { title: 'Перед началом' }),
  scale('Насколько сильны сейчас боль, обида, злость или раздражение?', 'before'),
  say('От всего сердца попроси у Бога прощения: «Господи, прости меня за то, что я причинил(а) кому-то боль и неприятности». Раз боль пришла к тебе — значит, когда-то её чувствовал кто-то другой.', { title: '1. Попроси прощения', big: true }),
  say('Покайся, чтобы искренность стала глубже: «Мне жаль, что я ранил(а) другого и он испытывал то же, что сейчас испытываю я. Прости меня, Господи, я раскаиваюсь».', { title: '2. Покайся', big: true }),
  say('Поблагодари Бога за то, что Он тебе это открывает: «Спасибо Тебе, Господи, что показываешь мне это. Спасибо за возможность понять, взглянуть на всё иначе и дальше поступать по-новому».', { title: '3. Поблагодари', big: true }),
  say('Скажи слова любви: «Господи, я люблю Тебя за Твою заботу и милость ко мне. Люблю Тебя всем сердцем».', { title: '4. Слова любви', big: true }),
  say('Закончи прощением себя: «Я прощаю себя за то, что причинил(а) кому-то боль. Прощаю за то, что тогда не сумел(а) поступить по-другому. Дай мне сил впредь поступать иначе и не ранить тех, кого я встречу». Помни: если бы тогда ты мог(ла) поступить иначе — ты бы так и сделал(а). Раз вышло так, значит, по-другому ты тогда не умел(а).', { title: '5. Прости себя', big: true }),
  scale('Насколько сильны боль, обида, злость или раздражение теперь?', 'after'),
];

