  ...vent('auth', 'авторитету', { words: null, prompt: 'Хочется показать ему(ей) что-то ещё? Может, тебе неловко стоять перед ним в таком виде?', done: 'Мне больше нечего показать', after: 'Скажи ему(ей): «Мне больше нечего тебе показать». Когда негативных чувств не останется — переходи ко второму этапу.' }),
